import { Injectable, Logger } from '@nestjs/common'
import { ConfigService } from '@nestjs/config'
import {
  S3Client,
  PutObjectCommand,
  DeleteObjectCommand,
  GetObjectCommand,
} from '@aws-sdk/client-s3'
import { getSignedUrl } from '@aws-sdk/s3-request-presigner'
import { createHmac, timingSafeEqual } from 'crypto'
import { promises as fs } from 'fs'
import { dirname, resolve, sep } from 'path'

// Object keys are generated by the API from IDs; this rejects anything that
// could escape the storage root if a key were ever built from user input.
function isSafeKey(key: string) {
  return (
    key.length > 0 &&
    key.length <= 1024 &&
    !key.startsWith('/') &&
    !/[\\\0]/.test(key) &&
    key.split('/').every((part) => part && part !== '.' && part !== '..')
  )
}

@Injectable()
export class StorageService {
  private readonly logger = new Logger(StorageService.name)

  // R2 (cloud) fields
  private readonly client: S3Client | null = null
  private readonly bucket: string

  // Local fallback
  private readonly isLocal: boolean
  private readonly uploadsDir: string

  constructor(private readonly config: ConfigService) {
    this.bucket = config.get<string>('R2_BUCKET_NAME', 'assessiq')
    this.uploadsDir = resolve(process.cwd(), 'uploads')

    const accessKeyId = config.get<string>('R2_ACCESS_KEY_ID', '')
    const endpoint = config.get<string>('R2_ENDPOINT', '')

    // Use local filesystem when R2 is not configured — development and tests only.
    this.isLocal = !accessKeyId || !endpoint
    if (this.isLocal && config.get<string>('NODE_ENV') === 'production')
      throw new Error('Object storage is required in production; refusing to store uploads on local disk')

    if (this.isLocal) {
      this.logger.warn(
        '⚠️  R2 credentials not configured — using LOCAL filesystem storage. ' +
          'Do not use this in production.',
      )
    } else {
      this.client = new S3Client({
        region: 'auto',
        endpoint,
        credentials: {
          accessKeyId,
          secretAccessKey: config.get<string>('R2_SECRET_ACCESS_KEY', ''),
        },
      })
    }
  }

  private localPath(key: string) {
    if (!isSafeKey(key)) throw new Error('Invalid storage key')
    const path = resolve(this.uploadsDir, key)
    if (!path.startsWith(this.uploadsDir + sep)) throw new Error('Invalid storage key')
    return path
  }

  // ─── Upload ────────────────────────────────────────────────────────────────

  async uploadBuffer(key: string, buffer: Buffer, _contentType: string): Promise<void> {
    if (this.isLocal) {
      const filePath = this.localPath(key)
      await fs.mkdir(dirname(filePath), { recursive: true })
      await fs.writeFile(filePath, buffer)
      this.logger.log(`[local] Saved ${key} (${buffer.length} bytes)`)
      return
    }

    await this.client!.send(
      new PutObjectCommand({
        Bucket: this.bucket,
        Key: key,
        Body: buffer,
        ContentType: _contentType,
      }),
    )
    this.logger.log(`[R2] Uploaded ${key} (${buffer.length} bytes)`)
  }

  // ─── Download URL ──────────────────────────────────────────────────────────

  // Every object is private: callers authorize the requester, then hand out a
  // short-lived URL. There is deliberately no permanent public-URL mode.
  async getSignedDownloadUrl(key: string, expiresInSeconds = 300): Promise<string> {
    if (this.isLocal) {
      this.localPath(key)
      const expires = Math.floor(Date.now() / 1000) + expiresInSeconds
      const apiBase = this.config.get<string>('API_URL', 'http://localhost:3001')
      const params = new URLSearchParams({ key, expires: String(expires), sig: this.sign(key, expires) })
      return `${apiBase}/api/v1/storage/local?${params}`
    }

    const command = new GetObjectCommand({ Bucket: this.bucket, Key: key })
    return getSignedUrl(this.client!, command, { expiresIn: expiresInSeconds })
  }

  private sign(key: string, expires: number) {
    const secret = this.config.getOrThrow<string>('JWT_SECRET')
    return createHmac('sha256', `local-storage:${secret}`).update(`${key}\n${expires}`).digest('hex')
  }

  /** Verifies a local signed URL and returns the file path, or null when invalid or expired. */
  verifyLocalUrl(key: string, expires: string, sig: string): string | null {
    if (!this.isLocal || !/^\d+$/.test(expires) || !/^[0-9a-f]{64}$/.test(sig)) return null
    if (Number(expires) < Date.now() / 1000) return null
    let path: string
    try {
      path = this.localPath(key)
    } catch {
      return null
    }
    const expected = Buffer.from(this.sign(key, Number(expires)), 'hex')
    return timingSafeEqual(expected, Buffer.from(sig, 'hex')) ? path : null
  }

  // ─── Delete ────────────────────────────────────────────────────────────────

  async delete(key: string): Promise<void> {
    if (this.isLocal) {
      await fs.unlink(this.localPath(key)).catch(() => undefined)
      this.logger.log(`[local] Deleted ${key}`)
      return
    }

    await this.client!.send(new DeleteObjectCommand({ Bucket: this.bucket, Key: key }))
    this.logger.log(`[R2] Deleted ${key}`)
  }
}
